CREATE TEMPORARY VIEW user_level_metrics_raw_${grass_region_without_quote} AS
select
    coalesce(platform, 'NULL') AS platform
    ,coalesce(cast(is_ads as string), 'false') as is_ads
    ,scenario_tag
    ,feature_detail
    ,case
        when feature_detail = '__ALL__' then '__ALL__'
        else if(split(feature_detail,'-')[2] IS NOT NULL, split(feature_detail,'-')[2], split(feature_detail,'-')[1])
    end as target_type
    ,user_id

    ,imp_cnt
    ,click_cnt
    ,ppv_cnt
    ,ppv_cnt_exclude_isback
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
from
    srdi_mart.dws_sr_data_warehouse_platform_user_level_benchmark_1d
where
    grass_region = ${grass_region}
    and local_date = ${local_date}
    and user_id > 0
    and (
        scenario_tag like 'DA_%'
        or scenario_tag = 'dpm module Global Search business line Search'
        or scenario_tag = '__ALL__'
    );

--sql_divide_splitter--
CREATE TEMPORARY VIEW user_level_metrics_${grass_region_without_quote} AS

select
    *
from
    user_level_metrics_raw_${grass_region_without_quote}

union all
select
    platform
    ,is_ads
    ,scenario_tag
    ,'__ALL__' as feature_detail
    ,target_type
    ,user_id

    ,sum(imp_cnt) as sum
    ,sum(click_cnt) as click_cnt
    ,sum(ppv_cnt) as ppv_cnt
    ,sum(ppv_cnt_exclude_isback) as ppv_cnt_exclude_isback
    ,sum(cart_cnt) as cart_cnt
    ,sum(order_cnt) as order_cnt
    ,sum(gmv) as gmv
    ,sum(pc2_gmv) as pc2_gmv
from
    user_level_metrics_raw_${grass_region_without_quote}
where
    scenario_tag != '__ALL__'
    and feature_detail != '__ALL__'
group by 1, 2, 3, 5, 6;

