CREATE TEMPORARY VIEW platform_metrics_${grass_region_without_quote} AS
select
    state
    ,platform
    ,is_ads
    ,scenario_tag
    ,feature_detail
    ,target_type
    ,exp_info.exp_group_id as exp_group_id

    ,cast(exp_info.fields[0] as bigint) as imp_uu
