    ,cast(exp_info.fields[2] as bigint) as ppv_uu
    ,cast(exp_info.fields[3] as bigint) as cart_uu
    ,cast(exp_info.fields[4] as bigint) as order_uu
    ,cast(exp_info.fields[5] as bigint) as imp_cnt
    ,cast(exp_info.fields[6] as bigint) as click_cnt
    ,cast(exp_info.fields[7] as bigint) as ppv_cnt
    ,cast(exp_info.fields[8] as bigint) as ppv_cnt_exclude_isback
    ,cast(exp_info.fields[9] as bigint) as cart_cnt
    ,exp_info.fields[10] as order_cnt
    ,exp_info.fields[11] as gmv
    ,exp_info.fields[12] as pc2_gmv
from
    metric_table_${grass_region_without_quote}
    LATERAL VIEW EXPLODE(exp_metrics) as exp_info;

