CREATE TEMPORARY VIEW user_level_gmv_raw_${grass_region_without_quote} AS
select
    user_id
    ,scenario_tag
    ,feature_detail
    ,coalesce(cast(is_ads as string), 'false') as is_ads
    ,gmv
    ,pc2_gmv
    ,imp_cnt
    ,order_cnt
from
    srdi_mart.dws_sr_data_warehouse_platform_user_level_benchmark_1d
where
    grass_region = ${grass_region}
    and local_date = ${local_date}
    and user_id > 0
    and (
        replace(scenario_tag, 'DA_', '') in (
            'Daily Discover', 'You May Also Like', 'Cart_Unify', 'Buy Again (Me Page)', 'Cart Recommendation',
            'odp_ymal-order_detail', 'Order Successful Recommendation', 'mpp_ymal-order_list',
            'Me YMAL', 'Shop YMAL', 'YMAL_Cart', 'RCMD Unify'
        )
        or scenario_tag = 'dpm module Global Search business line Search'
        or scenario_tag = '__ALL__'
    )
;

--sql_divide_splitter--
CREATE TEMPORARY VIEW user_level_gmv_${grass_region_without_quote} AS
select
    user_id
    ,scenario_tag
    ,'__ALL__' as target_type
    ,is_ads
    ,sum(gmv) as gmv
    ,sum(pc2_gmv) as pc2_gmv
    ,sum(imp_cnt) as imp_cnt
    ,sum(order_cnt) as order_cnt
from
    user_level_gmv_raw_${grass_region_without_quote}
where
    feature_detail = '__ALL__'
group by 1, 2, 4

union all
select
    user_id
    ,scenario_tag
    ,if(split(feature_detail,'-')[2] IS NOT NULL, split(feature_detail,'-')[2], split(feature_detail,'-')[1]) as target_type
    ,is_ads
    ,sum(gmv) as gmv
    ,sum(pc2_gmv) as pc2_gmv
    ,sum(imp_cnt) as imp_cnt
    ,sum(order_cnt) as order_cnt
from
    user_level_gmv_raw_${grass_region_without_quote}
where
    feature_detail != '__ALL__'
group by 1, 2, 3, 4
;

