--sql_divide_splitter--
CREATE TEMPORARY VIEW user_level_gmv_cube_${grass_region_without_quote} AS
select
    state
    ,scenario_tag
    ,target_type
    ,coalesce(is_ads, '__ALL__') as is_ads
    ,user_id
    ,coalesce(sum(gmv), 0) as gmv
    ,coalesce(sum(gmv) / sum(order_cnt), 0) as abs
    ,coalesce(sum(pc2_gmv), 0) as pc2_gmv
    ,coalesce(sum(imp_cnt), 0) as imp_cnt
from
    user_level_gmv_state_${grass_region_without_quote}
group by grouping sets (
    (state, scenario_tag, target_type, is_ads, user_id)
    ,(state, scenario_tag, target_type, user_id)
);

--sql_divide_splitter--
CREATE TEMPORARY VIEW abs_995_val_${grass_region_without_quote} AS
select
    case
        when feature_group = 'Search' then 'dpm module Global Search business line Search'
        when feature_group = 'all' then '__ALL__'
        when feature_group = 'Cart Unify' then 'DA_Cart_Unify'
        when feature_group = 'Order Detail Page YMAL' then 'DA_odp_ymal-order_detail'
        when feature_group = 'My Purchase Page YMAL' then 'DA_mpp_ymal-order_list'
        else concat('DA_', feature_group)
     end as scenario_tag
    ,case when is_ads = 'all' then '__ALL__' else is_ads end as is_ads
    ,max(val) as abs_995
from
    srdi_mart.ads_rcmd_platform_scenario_level_outlier_di
where
    grass_region = ${grass_region}
    and grass_date = ${local_date}
    and outlier_type = 'abs'
    and percentile = 0.995
group by 1, 2;

--sql_divide_splitter--
CREATE TEMPORARY VIEW metrics_995_map_data_${grass_region_without_quote} AS
select
    state
    ,user_id
    ,t1.is_ads
    ,t1.scenario_tag
    ,target_type
    ,array(
        sum(gmv) -- gmv_995
        ,sum(pc2_gmv) -- pc2_gmv_995
        ,max(if(imp_cnt > 0 and user_id > 0, 1, 0)) -- imp_uu
    ) as metrics
from
    user_level_gmv_cube_${grass_region_without_quote} as t1
left join
    abs_995_val_${grass_region_without_quote} as t2
on
    t1.scenario_tag = t2.scenario_tag
    and t1.is_ads = t2.is_ads
where
    coalesce(abs, 0) <= abs_995
group by 1, 2, 3, 4, 5;

