create TEMPORARY VIEW ads_metrics_map_data_${grass_region_without_quote} as
select
    COALESCE(state, 'Unknown') AS state
    ,scenario_tag
    ,t1.user_id
    ,array(
        sum(revenue_usd)
        ,sum(ads_gmv_usd)
        ,sum(ads_broad_gmv_local)/avg(fx)
        ,sum(ads_broad_order_cnt)
        ,sum(ads_order_cnt)
        ,sum(ads_imp_cnt)
        ,sum(ads_click_cnt)
    ) as metrics
from
    ads_metrics_raw_${grass_region_without_quote} as t1
left join
    user_state_mapping_${grass_region_without_quote} as t2
on t1.user_id = t2.user_id
left join
    fx_rate_${grass_region_without_quote} as t3
group by 1, 2, 3;

