CREATE TEMPORARY VIEW ads_metrics_cube_${grass_region_without_quote} AS
select
    state
    ,exp_group_id
    ,'__ALL__' as platform
    ,'true' as is_ads
    ,coalesce(scenario_tag, '__ALL__') as scenario_tag
    ,'__ALL__' as feature_detail
    ,'__ALL__' as target_type

    ,sum(revenue_usd) as revenue_usd
    ,sum(ads_gmv_usd) as ads_gmv_usd
    ,sum(ads_broad_gmv_usd) as ads_broad_gmv_usd
    ,sum(ads_broad_order_cnt) as ads_broad_order_cnt
    ,sum(ads_order_cnt) as ads_order_cnt
    ,sum(ads_imp_cnt) as ads_imp_cnt
    ,sum(ads_click_cnt) as ads_click_cnt
from
    ads_metrics_explode_${grass_region_without_quote}
group by grouping sets (
    (state, exp_group_id, scenario_tag)
    ,(state, exp_group_id)
)

union all
select
    state
    ,exp_group_id
    ,'__ALL__' as platform
    ,'true' as is_ads
    ,'DA_Cart_Unify' as scenario_tag
    ,'__ALL__' as feature_detail
    ,'__ALL__' as target_type

    ,sum(revenue_usd) as revenue_usd
    ,sum(ads_gmv_usd) as ads_gmv_usd
    ,sum(ads_broad_gmv_usd) as ads_broad_gmv_usd
    ,sum(ads_broad_order_cnt) as ads_broad_order_cnt
    ,sum(ads_order_cnt) as ads_order_cnt
    ,sum(ads_imp_cnt) as ads_imp_cnt
    ,sum(ads_click_cnt) as ads_click_cnt
from
    ads_metrics_explode_${grass_region_without_quote}
where scenario_tag in (
    'DA_Cart Recommendation', 'DA_Order Successful Recommendation',
    'DA_odp_ymal-order_detail', 'DA_mpp_ymal-order_list',
    'DA_Me YMAL', 'DA_Shop YMAL'
)
group by 1, 2

union all
select
    state
    ,exp_group_id
    ,'__ALL__' as platform
    ,'true' as is_ads
    ,'DA_RCMD Unify' as scenario_tag
    ,'__ALL__' as feature_detail
    ,'__ALL__' as target_type

    ,sum(revenue_usd) as revenue_usd
    ,sum(ads_gmv_usd) as ads_gmv_usd
    ,sum(ads_broad_gmv_usd) as ads_broad_gmv_usd
    ,sum(ads_broad_order_cnt) as ads_broad_order_cnt
    ,sum(ads_order_cnt) as ads_order_cnt
    ,sum(ads_imp_cnt) as ads_imp_cnt
    ,sum(ads_click_cnt) as ads_click_cnt
from
    ads_metrics_explode_${grass_region_without_quote}
where scenario_tag in (
    'DA_Cart Recommendation', 'DA_Order Successful Recommendation',
    'DA_odp_ymal-order_detail', 'DA_mpp_ymal-order_list',
    'DA_Me YMAL', 'DA_Shop YMAL',
    'DA_You May Also Like', 'DA_Daily Discover'
)
group by 1, 2

union all
select
    state
    ,exp_group_id
    ,'__ALL__' as platform
    ,'true' as is_ads
    ,'DA_YMAL_Cart' as scenario_tag
    ,'__ALL__' as feature_detail
    ,'__ALL__' as target_type

    ,sum(revenue_usd) as revenue_usd
    ,sum(ads_gmv_usd) as ads_gmv_usd
    ,sum(ads_broad_gmv_usd) as ads_broad_gmv_usd
    ,sum(ads_broad_order_cnt) as ads_broad_order_cnt
    ,sum(ads_order_cnt) as ads_order_cnt
    ,sum(ads_imp_cnt) as ads_imp_cnt
    ,sum(ads_click_cnt) as ads_click_cnt
from
    ads_metrics_explode_${grass_region_without_quote}
where scenario_tag in (
    'DA_Cart Recommendation', 'DA_Order Successful Recommendation',
    'DA_odp_ymal-order_detail', 'DA_mpp_ymal-order_list',
    'DA_Me YMAL', 'DA_Shop YMAL',
    'DA_You May Also Like'
)
group by 1, 2
;

--sql_divide_splitter--
INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_platform_exp_state_level_metrics_1d
PARTITION (exp_type = 'dim_join', grass_region = ${grass_region}, local_date = ${local_date})

select
    coalesce(t1.state, t3.state) as state
    ,coalesce(t1.exp_group_id, t3.exp_group_id) as exp_group_id
    ,coalesce(t1.platform, t3.platform) as platform
    ,coalesce(t1.is_ads, t3.is_ads) as is_ads
    ,coalesce(t1.scenario_tag, t3.scenario_tag) as scenario_tag
    ,coalesce(t1.feature_detail, t3.feature_detail) as feature_detail
    ,coalesce(t1.target_type, t3.target_type) as target_type

    ,imp_uu
    ,click_uu
    ,ppv_uu
    ,cart_uu
    ,order_uu
    ,imp_cnt
    ,click_cnt
    ,ppv_cnt
    ,ppv_cnt_exclude_isback
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv

    ,gmv_995
    ,pc2_gmv_995
    ,imp_uu_995

    ,revenue_usd
    ,ads_gmv_usd
    ,ads_broad_gmv_usd
    ,ads_broad_order_cnt
    ,ads_order_cnt
    ,ads_imp_cnt
    ,ads_click_cnt

from
    platform_metrics_${grass_region_without_quote} as t1
left join
    metrics_995_${grass_region_without_quote} as t2
on
    t1.state = t2.state
    and t1.exp_group_id = t2.exp_group_id
    and t1.platform = t2.platform
    and t1.is_ads = t2.is_ads
    and t1.scenario_tag = t2.scenario_tag
    and t1.feature_detail = t2.feature_detail
    and t1.target_type = t2.target_type
full outer join
    ads_metrics_cube_${grass_region_without_quote} as t3
on
    t1.state = t3.state
    and t1.exp_group_id = t3.exp_group_id
    and t1.platform = t3.platform
    and t1.is_ads in ('true', '__ALL__')
    and t1.scenario_tag = t3.scenario_tag
    and t1.feature_detail = t3.feature_detail
    and t1.target_type = t3.target_type
